// checked against the papers. Data: data/rq1-film.json (evolution film), rq1-landscape.json (the field over time under one
// retrospective scheme), rq1-cases.json (case material with source sentences), rq1-checks.json (verification numbers).
// Data files stay English; the reading text is here.
let film = null, land = null, cases = null, checks = null, units = null, lives = null, rq2 = null, tl = null, fd = null, dlv = null, player = null, tab = null;

export async function loadRq() {
  if (film) return;
  const get = n => fetch(`./data/${n}`).then(r => { if (!r.ok) throw new Error(n); return r.json() });
  [film, cases, lives] = await Promise.all([get('rq1-film.json'), get('rq1-cases.json'), get('rq-lineages.json')]);
}

