const INPUT = { task_specification: ['Task specification', '任务说明'], provenance_labels: ['Provenance labels', '来源标签'], security_policy: ['Security policy', '安全策略'],
  authorization_or_credentials: ['Authorisation or credentials', '授权或凭证'], tool_metadata: ['Tool metadata', '工具元数据'], model_judgement: ["A model's judgement", '模型的判断'], other: ['Other inputs', '其他输入'] };
const PRODUCER = { user: ['user', '用户'], developer_or_operator: ['developer or operator', '开发者或运营方'], platform_or_runtime: ['platform or runtime', '平台或运行时'], the_model_itself: ['the model', '模型自身'], third_party: ['third party', '第三方'], not_stated: ['not stated', '未说明'] };
const KEPT = { memory_storage: ['memory', '记忆保存'], later_tasks_or_sessions: ['later tasks', '之后的任务或会话'], summarisation: ['summarising', '摘要'], handoff_to_other_agent: ['handover', 'Agent 间转交'] };
