  const g = k => sysRows.find(r => r.input === k) || { papers: 0, produced_by: {}, attacker: {}, kept: {}, kept_any: 0, kind: {}, via: {} };
  const tg = r => (r.kind.V || 0) + (r.kind.C || 0);
