  const VIA = { interface: t('through an interface the attacker controls', '经由攻击者可控的接口'), root: t('a trusted record or key corrupted directly', '直接破坏可信记录或密钥'), generation: t('errors of the component that produces it', '生成该输入的组件出错') };
