function mdHtml(md) {
  const inl = x => esc(x).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>').replace(/`([^`]+)`/g, '<code>$1</code>');
  const out = [], L = md.split('\n'); let i = 0;
  while (i < L.length) {
    const l = L[i];
    if (/^\|/.test(l)) {
      const rows = []; while (i < L.length && /^\|/.test(L[i])) { rows.push(L[i]); i++ }
      const cells = r => r.replace(/^\||\|$/g, '').split('|').map(c => c.trim());
      const body = rows.filter((r, k) => k !== 1 || !/^\|[\s\-:|]+\|$/.test(r));
      out.push(`<div class="rq-scroll"><table class="rq-summary rq-wide"><thead><tr>${cells(body[0]).map(c => `<th>${inl(c)}</th>`).join('')}</tr></thead><tbody>${body.slice(1).map(r => `<tr>${cells(r).map(c => `<td>${inl(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);
      continue;
    }
    if (/^- /.test(l) || /^  - /.test(l)) {
      const items = []; while (i < L.length && /^\s*- /.test(L[i])) { items.push(L[i].replace(/^\s*- /, '')); i++ }
      out.push(`<ul class="rq-list">${items.map(x => `<li>${inl(x)}</li>`).join('')}</ul>`); continue;
    }
    if (/^```/.test(l)) { const b = []; i++; while (i < L.length && !/^```/.test(L[i])) { b.push(L[i]); i++ } i++; out.push(`<pre>${esc(b.join('\n'))}</pre>`); continue; }
    const h = l.match(/^(#{1,3}) (.*)/);
    if (h) out.push(h[1].length === 1 ? '' : `<h${h[1].length + 1}>${inl(h[2])}</h${h[1].length + 1}>`);
    else if (l.trim()) out.push(`<p>${inl(l)}</p>`);
    i++;
  }
  return out.join('');
}
